function Router({ store, loading, error }: {
    store: ShopezStore | null;
    loading: boolean;
    error: string;
}) { const path = location.pathname.replace(/\/$/, '') || '/'; if (path === '/')
    return <HomePage store={store} loading={loading} error={error}/>; if (path === '/shop')
    return <ShopPage store={store} loading={loading} error={error}/>; if (path.startsWith('/products/'))
    return <ProductPage store={store} loading={loading}/>; if (path === '/cart')
    return <CartPage />; if (path === '/checkout')
    return <CheckoutPage store={store}/>; if (path === '/account')
    return <AccountPage store={store}/>; if (path === '/our-ritual')
    return <RitualPage />; if (path === '/uae-story')
    return <UaePage />; if (path === '/journal')
    return <JournalPage />; if (path === '/policies')
    return <PoliciesPage />; return <PageState title="This path has wandered beyond the meadow." link="/"/>; }
function App() { const [store, setStore] = useState<ShopezStore | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); useEffect(() => { const controller = new AbortController(); loadShopezStore(controller.signal).then(setStore).catch(reason => { if (reason.name !== 'AbortError')
    setError(reason.message); }).finally(() => setLoading(false)); return () => controller.abort(); }, []); return <CartProvider store={store}><Header /><Router store={store} loading={loading} error={error}/><Footer /></CartProvider>; }
createRoot(document.getElementById('root')!).render(<React.StrictMode><App /></React.StrictMode>);
